const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');
const { DatabaseSync } = require('node:sqlite');
const { extractPrimary } = require('./primary-source.cjs');
const { execFile } = require('node:child_process');
const { promisify } = require('node:util');
const execute = promisify(execFile);
const digest = value => createHash('sha256').update(typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value)).digest('hex');
const now = () => new Date().toISOString();
const roles = ['planner', 'manager', 'analysis', 'literature', 'synthesis', 'audit', 'main'];
const safeId = value => typeof value === 'string' && /^[a-zA-Z0-9_-]{1,100}$/.test(value);
function requireRole(actor, allowed) { if (!allowed.includes(actor)) throw new Error('Operation not assigned to this role'); }

function validateClaims(claims, state) {
  if (!Array.isArray(claims) || !claims.length || claims.length > 30) throw new Error('Supply 1..30 evidence-backed claims');
  const current = new Set(state.claims.map(claim => claim.id));
  const knownEvidence = new Set([...Object.keys(state.sources), ...Object.values(state.jobs).filter(job => job.status === 'succeeded').map(job => job.id)]);
  const seen = new Set();
  for (const claim of claims) {
    if (!safeId(claim.id) || current.has(claim.id) || seen.has(claim.id)) throw new Error('Duplicate or unsafe claim id');
    seen.add(claim.id);
    if (!['analysis', 'literature', 'interpretation'].includes(claim.kind) || typeof claim.text !== 'string' || !claim.text.trim() || claim.text.length > 6000) throw new Error('Invalid typed claim');
    if (!Array.isArray(claim.evidenceIds) || !claim.evidenceIds.length || claim.evidenceIds.some(id => !knownEvidence.has(id))) throw new Error('Unknown or missing provenance');
    if (claim.kind === 'analysis' && !claim.evidenceIds.some(id => Object.values(state.jobs).some(job => job.id === id && job.status === 'succeeded'))) throw new Error('Analysis claim needs an actual successful job');
    if (claim.kind === 'literature' && !claim.evidenceIds.some(id => state.sources[id]?.fullText)) throw new Error('Literature claim needs a retrieved source, not fabricated bibliography');
    for (const key of ['supports', 'contradicts', 'supersedes']) {
      if (claim[key] !== undefined && (!Array.isArray(claim[key]) || claim[key].some(id => !current.has(id)))) throw new Error('Relationships must reference already persisted claims');
    }
  }
}

function openStore(root, actor) {
  if (!path.isAbsolute(root) || !roles.includes(actor)) throw new Error('Explicit scientific state directory and known actor required');
  const config = JSON.parse(fs.readFileSync(path.join(root, 'settings.json'), 'utf8'));
  if (config.method !== 'kosmos' || !Number.isInteger(config.maxCycles) || config.maxCycles < 2) throw new Error('Invalid Kosmos experiment settings');
  const db = new DatabaseSync(path.join(root, 'world.sqlite'));
  db.exec('PRAGMA busy_timeout=5000');
  for(let attempt=0;;attempt++){
    try{
      if(db.prepare('PRAGMA journal_mode').get().journal_mode!=='wal') db.exec('PRAGMA journal_mode=WAL');
      db.exec('CREATE TABLE IF NOT EXISTS state (id INTEGER PRIMARY KEY, json TEXT NOT NULL); CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, hash TEXT NOT NULL, status TEXT NOT NULL, result TEXT);');
      break;
    }catch(error){
      if(![5,6].includes(error.errcode)||attempt>=80){db.close();throw error;}
      // SQLite journal-mode lock upgrades can fail without honoring busy_timeout.
      // Bounded cold-start retry only; no replay of scientific side effects.
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,25);
    }
  }
  db.prepare('INSERT OR IGNORE INTO state(id,json) VALUES (1,?)').run(JSON.stringify({ version: 0, cycle: 0, cycles: [], claims: [], sources: {}, jobs: {}, queries: [], audit: null }));
  const read = () => JSON.parse(db.prepare('SELECT json FROM state WHERE id=1').get().json);
  const mutate = (change, advanceVersion = true) => {
    db.exec('BEGIN IMMEDIATE');
    try {
      const state = read(); const result = change(state);
      if (advanceVersion) state.version++; db.prepare('UPDATE state SET json=? WHERE id=1').run(JSON.stringify(state)); db.exec('COMMIT'); return result;
    } catch (error) { db.exec('ROLLBACK'); error.transactionRolledBack = true; throw error; }
  };
  async function once(name, args, action) {
    if (!safeId(args.requestId)) throw new Error('Stable requestId required');
    const id = `${actor}:${name}:${args.requestId}`, hash = digest(args);
    db.exec('BEGIN IMMEDIATE');
    try {
      const previous = db.prepare('SELECT * FROM requests WHERE id=?').get(id);
      if (previous) {
        if (previous.hash !== hash) throw new Error('Idempotency key reused for different arguments');
        if (previous.status !== 'complete') throw new Error('Prior operation is pending or uncertain; inspect retained job instead of repeating it');
        db.exec('COMMIT'); return JSON.parse(previous.result);
      }
      db.prepare('INSERT INTO requests(id,hash,status) VALUES (?,?,?)').run(id, hash, 'pending'); db.exec('COMMIT');
    } catch (error) { if (db.isTransaction) db.exec('ROLLBACK'); throw error; }
    // A crash after an external side effect remains pending, never silently reissued.
    let result;
    try { result = await action(); }
    catch (error) {
      // Rejected pure state transactions did not commit a scientific side effect.
      // Preserve pending for uncertain external source/container actions only.
      if (error.transactionRolledBack && ['plan_cycle', 'publish_trajectory', 'update_world', 'record_audit'].includes(name)) db.prepare('DELETE FROM requests WHERE id=? AND status=?').run(id, 'pending');
      throw error;
    }
    db.prepare('UPDATE requests SET status=?,result=? WHERE id=?').run('complete', JSON.stringify(result), id);
    return result;
  }
  const context = () => {
    const state = read();
    return { method: config.method, objective: config.objective, maxCycles: config.maxCycles, currentCycle: state.cycle, version: state.version,
      datasets: config.datasets.map(({ name, file, sha256 }) => ({ name, file, sha256 })),
      inputDirectoryInContainer: '/input', outputDirectoryInContainer: '/output',
      cycles: state.cycles, claims: state.claims, sources: Object.values(state.sources).map(({ id, url, title, sha256, fullText }) => ({ id, url, title, sha256, fullText })),
        jobs: Object.values(state.jobs).map(job=>({id:job.id,actor:job.actor,cycle:job.cycle,status:job.status,codeSha256:job.codeSha256,artifacts:job.artifacts,jobDir:job.jobDir,error:job.error?.slice(0,2000)})), audit: state.audit,
        primarySourceCatalog: config.primarySourceCatalog ?? [],
        note: 'Job command/full stdout are exported through write_evidence_artifacts, not repeated in every model context.' };
  };
  const operations = {
    get_context: async () => context(),
    get_dispatch_plan: async () => {
      requireRole(actor, ['manager']);
      const state=read(),cycle=state.cycles.at(-1);
      if(!cycle||cycle.synthesizedAt)throw new Error('No active unsynthesized scientific cycle to dispatch');
      return {cycle:cycle.cycle,version:state.version,tasks:cycle.tasks.map(task=>({taskId:task.actor==='analysis'?'data_traj':'literature_traj',assignment:`CURRENT SCIENTIFIC CYCLE ${cycle.cycle} ONLY. First call science get_assignment. Do not run two cycles in this group. Upstream planner PRs are not your business-completion receipts. ${task.assignment}`})),instruction:'Copy these exact taskId/assignment pairs into native assign_group_tasks with this Inbox groupRunId/coordinatorEpoch and a fresh callId. This tool does NOT dispatch or grant orchestration authority. Stop the planning turn after formal assignment and finish_task; the next cycle follows synthesis in a later group.'};
    },
    get_assignment: async () => {
      requireRole(actor, ['analysis','literature']);
      const state=read(),cycle=state.cycles.at(-1),task=cycle?.tasks.find(task=>task.actor===actor);
      if(!task||cycle.synthesizedAt)throw new Error('No active scientific task for this worker');
      const trajectory=cycle.trajectories.find(item=>item.actor===actor)??null;
      return {actor,cycle:cycle.cycle,assignment:task.assignment,usedClaimIds:cycle.usedClaimIds,scientificWorkComplete:!!trajectory,trajectory,
        datasets:config.datasets.map(({name,file,sha256})=>({name,file,sha256})),primarySourceCatalog:actor==='literature'?(config.primarySourceCatalog??[]):undefined,
        instruction:trajectory?'This actor published real scientific evidence in this cycle. Preserve it; perform only remaining authorized delivery.':'Scientific work is NOT complete. Native role=delivery on a first worker turn permits business plus Git; it does NOT prove a closure-only turn. Predecessor/parent PRs cannot complete this worker. Execute this single-cycle assignment, publish_trajectory with genuine evidence, export the scientific results, then do your own Git delivery. Memory.md alone is not scientific output.'};
    },
    get_synthesis_assignment: async () => {
      requireRole(actor, ['synthesis']);
      const state=read(),cycle=state.cycles.at(-1);
      if(!cycle)throw new Error('No actual planned scientific cycle for synthesis');
      const addedClaimIds=cycle.addedClaimIds??[];
      const complete=Boolean(cycle.synthesizedAt)&&addedClaimIds.length>0&&addedClaimIds.every(id=>state.claims.some(claim=>claim.id===id&&claim.cycle===cycle.cycle));
      return {actor,cycle:cycle.cycle,version:state.version,scientificWorkComplete:complete,
        synthesizedAt:cycle.synthesizedAt??null,addedClaimIds,trajectories:cycle.trajectories,
        assignment:complete?'Preserve this actual completed world-update receipt and supplement only authorized remaining delivery.':'Read both current published trajectories and actual run/source evidence. Discover and call update_world to create your own typed evidence-backed claims, then export the world and write the current-cycle synthesis report. Readiness or an upstream PR is not your completion.',
        nativeDeliveryBoundary:'Synthesis is a root business role. Use the exact current native Inbox branch, confirmed pushed head and direct target main; never copy the predecessor group/member PR target. This scientific tool does not grant Git or scheduling authority.'};
    },
      get_cycle_readiness: async () => {
        const state=read(),cycle=state.cycles.at(-1),actors=cycle?.trajectories.map(item=>item.actor)??[];
        const missing=['analysis','literature'].filter(actor=>!actors.includes(actor));
        const literature=cycle?.trajectories.filter(item=>item.actor==='literature')??[];
        const validLiterature=literature.length===1&&literature.every(item=>item.evidenceIds.every(id=>state.sources[id]?.titleVerified));
        return {cycle:state.cycle,ready:missing.length===0&&validLiterature,missingActors:missing,validLiterature,titleVerificationRequired:true,synthesisComplete:Boolean(cycle?.synthesizedAt),instruction:'Ready means prerequisites for synthesis, NOT that synthesis was done. Scientific publication and native Git integration are distinct. Do not close this group or dispatch synthesis with missing/invalid scientific trajectories; synthesis must read its own get_synthesis_assignment and actual world-update receipt.'};
      },
    query_world: async ({ query }) => mutate(state => {
      if (typeof query !== 'string' || !query.trim() || query.length > 2000) throw new Error('Specify a bounded scientific query');
      const terms = query.toLowerCase().split(/\W+/).filter(term => term.length > 2);
      const matches = state.claims.filter(claim => claim.status !== 'superseded').map(claim => ({ claim, rank: terms.filter(term => claim.text.toLowerCase().includes(term)).length }))
        .sort((a, b) => b.rank - a.rank).slice(0, 20).map(item => item.claim);
      state.queries.push({ actor, query, cycle: state.cycle, version: state.version, claimIds: matches.map(claim => claim.id), at: now() });
      return { version: state.version, claims: matches, query, note: 'Transparent lexical index and typed claim links; not the unpublished Kosmos index implementation.' };
    }, false),
    plan_cycle: async args => {
      requireRole(actor, ['planner']);
      return once('plan_cycle', args, async () => mutate(state => {
        if (args.expectedVersion !== state.version) throw new Error('Stale world version; read/query the current world first');
        if (state.cycle >= config.maxCycles) throw new Error('Authorized cycle budget exhausted');
        if (state.cycle && !state.cycles.at(-1).synthesizedAt) throw new Error('Previous cycle must be synthesized before planning another');
        if (!Array.isArray(args.tasks) || args.tasks.length !== 2 || new Set(args.tasks.map(task => task.actor)).size !== 2 || !args.tasks.some(task => task.actor === 'analysis') || !args.tasks.some(task => task.actor === 'literature')) throw new Error('Plan one actual data and one literature trajectory in parallel');
        const used = args.usedClaimIds ?? [];
        if (used.some(id => !state.claims.some(claim => claim.id === id))) throw new Error('Unknown reused claim');
        if (state.cycle && (!used.length || !state.queries.some(q => q.actor === actor && q.cycle === state.cycle && used.every(id => q.claimIds.includes(id))))) throw new Error('Next cycle must actually query and consume earlier world-model claims');
        for (const task of args.tasks) if (typeof task.assignment !== 'string' || !task.assignment.trim() || task.assignment.length > 12000) throw new Error('Each trajectory needs a concrete assignment');
        state.cycle++; state.cycles.push({ cycle: state.cycle, tasks: args.tasks, usedClaimIds: used, trajectories: [], plannedAt: now(), plannedFromVersion: args.expectedVersion });
        return { cycle: state.cycle, tasks: args.tasks, usedClaimIds: used };
      }));
    },
    search_literature: async args => {
      requireRole(actor, ['literature']);
      if (typeof args.query !== 'string' || !args.query.trim() || args.query.length > 400) throw new Error('Bounded literature query required');
      const url = new URL('https://api.crossref.org/works'); url.searchParams.set('query', args.query); url.searchParams.set('rows', '5');
      const response = await fetch(url, { signal: AbortSignal.timeout(45000) }); if (!response.ok) throw new Error(`Crossref HTTP ${response.status}`);
      const body = await response.json();
      return { query: args.query, url: String(url), results: body.message.items.map(item => ({ doi: item.DOI, title: item.title?.[0], url: item.URL, abstract: item.abstract, authors: item.author?.slice(0, 3).map(a => `${a.given ?? ''} ${a.family ?? ''}`), note: 'Metadata only. Retrieve primary full text before treating as read evidence.' })) };
    },
    read_primary_source: async args => {
      requireRole(actor, ['literature']);
      return once('read_primary_source', args, async () => {
        let url = new URL(args.url);
        const allowed = new Set(['arxiv.org', 'pmc.ncbi.nlm.nih.gov', 'www.ebi.ac.uk']);
        if (url.protocol !== 'https:' || !allowed.has(url.hostname) || url.username || url.password) throw new Error('Only public arXiv/PMC primary full-text sources are enabled');
        let response;
        for (let hop = 0; hop < 4; hop++) {
          response = await fetch(url, { redirect: 'manual', signal: AbortSignal.timeout(45000) });
          if (response.status < 300 || response.status >= 400) break;
          url = new URL(response.headers.get('location'), url);
          if (url.protocol !== 'https:' || !allowed.has(url.hostname)) throw new Error('Refusing source redirect outside the enabled public hosts');
        }
        if (!response.ok) throw new Error(`Primary source HTTP ${response.status}`);
        if (Number(response.headers.get('content-length')) > 4 * 1024 ** 2) throw new Error('Source exceeds 4 MiB');
        const chunks = []; let length = 0;
        for await (const chunk of response.body) { length += chunk.length; if (length > 4 * 1024 ** 2) throw new Error('Source exceeds 4 MiB'); chunks.push(chunk); }
        const raw = Buffer.concat(chunks).toString('utf8');
        const verified = extractPrimary(raw, String(url), args.title), plain = verified.plain;
        const sha256 = digest(raw), id = `source_${sha256.slice(0, 20)}`;
        const offset = Number.isInteger(args.offset) && args.offset >= 0 ? args.offset : 0;
        const source = { id, url: String(url), title: verified.title, requestedTitle: args.title, sha256, fullText: true, titleVerified: true, retrievedAt: now(), bytes: length, characters: plain.length };
        fs.mkdirSync(path.join(root, 'sources'), { recursive: true }); fs.writeFileSync(path.join(root, 'sources', `${id}.txt`), plain); fs.writeFileSync(path.join(root, 'sources', `${id}.html`), raw);
        mutate(state => { state.sources[id] = source; });
        return { ...source, offset, text: plain.slice(offset, offset + 18000), truncated: offset + 18000 < plain.length };
      });
    },
    run_analysis: async args => {
      requireRole(actor, ['analysis']);
      return once('run_analysis', args, async () => {
        if (typeof args.code !== 'string' || !args.code.trim() || args.code.length > 80000) throw new Error('Actual Python analysis code required');
        const state = read(), cycle = state.cycle;
        if (!cycle || state.cycles.at(-1).synthesizedAt) throw new Error('No open planned cycle');
        const id = `run_${digest({ actor, cycle, requestId: args.requestId, code: args.code }).slice(0, 20)}`, jobDir = path.join(root, 'jobs', id), outputDir = path.join(jobDir, 'output');
        fs.mkdirSync(outputDir, { recursive: true }); fs.writeFileSync(path.join(jobDir, 'script.py'), args.code);
        const record = { id, actor, cycle, codeSha256: digest(args.code), status: 'running', startedAt: now(), image: config.image, datasetHashes: config.datasets.map(({ file, sha256 }) => ({ file, sha256 })) };
        mutate(s => { s.jobs[id] = record; });
        const command = ['run', '--rm', '--name', `scienceevolve-${id}`, '--label', `scienceevolve.todo.job=${id}`, '--network', 'none', '--read-only', '--cap-drop', 'ALL', '--security-opt', 'no-new-privileges', '--cpus', '2', '--memory', '2g', '--pids-limit', '128', '--tmpfs', '/tmp:rw,size=256m', '--mount', `type=bind,source=${config.inputDir},target=/input,readonly`, '--mount', `type=bind,source=${path.join(jobDir, 'script.py')},target=/work/script.py,readonly`, '--mount', `type=bind,source=${outputDir},target=/output`, config.image, 'python', '/work/script.py'];
        let stdout = '', stderr = '', success = false;
        try { ({ stdout, stderr } = await execute('docker', command, { timeout: 240000, maxBuffer: 2 * 1024 ** 2, windowsHide: true })); success = true; }
        catch (error) {
          stdout = error.stdout ?? ''; stderr = error.stderr ?? String(error.message);
          if (error.killed) {
            const label = await execute('docker', ['inspect', '--format', '{{index .Config.Labels "scienceevolve.todo.job"}}', `scienceevolve-${id}`], { windowsHide: true }).catch(() => null);
            if (label?.stdout.trim() === id) await execute('docker', ['stop', '--time', '5', `scienceevolve-${id}`], { windowsHide: true }).catch(() => {});
          }
        }
        fs.writeFileSync(path.join(jobDir, 'stdout.log'), stdout); fs.writeFileSync(path.join(jobDir, 'stderr.log'), stderr);
        const artifacts = [];
        for (const entry of fs.readdirSync(outputDir, { withFileTypes: true })) {
          if (!entry.isFile() || entry.isSymbolicLink() || fs.statSync(path.join(outputDir, entry.name)).size > 8 * 1024 ** 2) continue;
          const bytes = fs.readFileSync(path.join(outputDir, entry.name));
          artifacts.push({ file: entry.name, sha256: digest(bytes), bytes: bytes.length });
        }
        const resultFile = path.join(outputDir, 'results.json');
        let metrics;
        try { metrics = JSON.parse(fs.readFileSync(resultFile, 'utf8')); } catch { success = false; }
        if (!artifacts.length) success = false;
        const result = { ...record, status: success ? 'succeeded' : 'failed', finishedAt: now(), metrics, artifacts, stdout: stdout.slice(-12000), stderr: stderr.slice(-12000), command, jobDir };
        mutate(s => { s.jobs[id] = result; }); return result;
      });
    },
    publish_trajectory: async args => {
      requireRole(actor, ['analysis', 'literature']);
      return once('publish_trajectory', args, async () => mutate(state => {
        const cycle = state.cycles.at(-1); if (!cycle || cycle.synthesizedAt) throw new Error('No active cycle');
        if (cycle.trajectories.some(item => item.actor === actor)) throw new Error('Trajectory already published');
        if (typeof args.finding !== 'string' || !args.finding.trim()) throw new Error('Actual trajectory findings required');
        const evidence = args.evidenceIds;
        if (!Array.isArray(evidence) || !evidence.length) throw new Error('Actual evidence required');
        for (const id of evidence) {
          if (actor === 'analysis' && !(state.jobs[id]?.status === 'succeeded' && state.jobs[id].cycle === state.cycle)) throw new Error('Analysis evidence must reference this cycle actual container results');
            if (actor === 'literature' && !(state.sources[id]?.fullText && state.sources[id]?.titleVerified)) throw new Error('Literature evidence must reference identity-verified retrieved primary sources');
        }
        const used = args.usedClaimIds ?? [];
        if (used.some(id => !state.claims.some(claim => claim.id === id))) throw new Error('Unknown reused claim');
        if (state.cycle > 1 && (!used.length || !state.queries.some(q => q.actor === actor && q.cycle === state.cycle && used.every(id => q.claimIds.includes(id))))) throw new Error('Later trajectory must actually read and consume previous claims');
        const record = { actor, cycle: state.cycle, finding: args.finding, evidenceIds: evidence, usedClaimIds: used, publishedAt: now() };
        cycle.trajectories.push(record); return record;
      }));
    },
    update_world: async args => {
      requireRole(actor, ['synthesis']);
      return once('update_world', args, async () => mutate(state => {
        const cycle = state.cycles.at(-1); if (!cycle || cycle.synthesizedAt || cycle.trajectories.length !== 2) throw new Error('Exactly two completed parallel trajectories required before world synthesis');
        validateClaims(args.claims, state);
        for (const claim of args.claims) {
          for (const id of claim.supersedes ?? []) state.claims.find(old => old.id === id).status = 'superseded';
          state.claims.push({ ...claim, cycle: state.cycle, createdAt: now(), status: 'active' });
        }
        cycle.synthesizedAt = now(); cycle.addedClaimIds = args.claims.map(claim => claim.id);
        return { version: state.version + 1, cycle: state.cycle, addedClaimIds: cycle.addedClaimIds };
      }));
    },
    write_evidence_artifacts: async () => {
      requireRole(actor, ['planner', 'analysis', 'literature', 'synthesis', 'audit']);
      const state = read(); const cycle = state.cycles.at(-1);
      const relative = `results/${actor}/cycle-${state.cycle}`;
      const local = path.join(process.cwd(), ...relative.split('/')); fs.mkdirSync(local, { recursive: true });
      const exportState = actor === 'synthesis' || actor === 'audit' ? context() : { actor, cycle, jobs: Object.values(state.jobs).filter(job => job.actor === actor && job.cycle === state.cycle), sources: actor === 'literature' ? Object.values(state.sources) : [] };
      fs.writeFileSync(path.join(local, 'evidence.json'), JSON.stringify(exportState, null, 2));
      if (actor === 'analysis') for (const job of Object.values(state.jobs).filter(job => job.actor === actor && job.cycle === state.cycle)) {
        fs.copyFileSync(path.join(job.jobDir, 'script.py'), path.join(local, `${job.id}.py`));
        for (const artifact of job.artifacts ?? []) fs.copyFileSync(path.join(job.jobDir, 'output', artifact.file), path.join(local, `${job.id}-${artifact.file}`));
      }
      return { relativePath: relative, evidenceSha256: digest(fs.readFileSync(path.join(local, 'evidence.json'))), note: 'Commit these files and your report through the assigned native SDK Git tools; this tool does not commit or complete the task.' };
    },
    read_reference_results: async () => {
      requireRole(actor, ['audit']);
      const bytes = fs.readFileSync(config.referenceFile);
      return { sha256: digest(bytes), text: bytes.toString('utf8'), note: 'Published reference is audit-only, not this run analysis input.' };
    },
    record_audit: async args => {
      requireRole(actor, ['audit']);
      return once('record_audit', args, async () => mutate(state => {
        if (state.cycle !== config.maxCycles || state.cycles.some(cycle => !cycle.synthesizedAt || cycle.trajectories.length !== 2)) throw new Error('All authorized cycles must have actual parallel trajectories and synthesis');
        if (!state.claims.some(claim => claim.kind === 'analysis') || !state.claims.some(claim => claim.kind === 'literature')) throw new Error('Typed data and literature claims required');
        if (Object.values(state.sources).filter(source => source.fullText).length < 2) throw new Error('Two distinct actually retrieved primary sources required');
        if (!state.cycles.slice(1).every(cycle => cycle.usedClaimIds.length && cycle.trajectories.every(t => t.usedClaimIds.length))) throw new Error('Cross-cycle world-model consumption not proven');
        if (!Array.isArray(args.checkedClaimIds) || state.claims.some(claim => !args.checkedClaimIds.includes(claim.id))) throw new Error('Independently inspect every claim before audit');
        if (typeof args.assessment !== 'string' || !args.assessment.trim()) throw new Error('Actual audit rationale required');
        state.audit = { at: now(), checkedClaimIds: args.checkedClaimIds, assessment: args.assessment, passed: args.passed === true, note: 'Protocol evidence audit, not reproduction of original paper numerical results or expert validation.' };
        return state.audit;
      }));
    }
  };
  return { operations, context, close: () => db.close(), read };
}
