    },
    read_primary_source: async args => {
      requireRole(actor, ['literature']);
      return once('read_primary_source', args, async () => {
        let url = new URL(args.url);
        const allowed = new Set(['arxiv.org', 'pmc.ncbi.nlm.nih.gov', 'www.ebi.ac.uk']);
        if (url.protocol !== 'https:' || !allowed.has(url.hostname) || url.username || url.password) throw new Error('Only public arXiv/PMC primary full-text sources are enabled');
        let response;
