        const offset = Number.isInteger(args.offset) && args.offset >= 0 ? args.offset : 0;
        const source = { id, url: String(url), title: verified.title, requestedTitle: args.title, sha256, fullText: true, titleVerified: true, retrievedAt: now(), bytes: length, characters: plain.length };
        fs.mkdirSync(path.join(root, 'sources'), { recursive: true }); fs.writeFileSync(path.join(root, 'sources', `${id}.txt`), plain); fs.writeFileSync(path.join(root, 'sources', `${id}.html`), raw);
