    },
    run_analysis: async args => {
      requireRole(actor, ['analysis']);
      return once('run_analysis', args, async () => {
        if (typeof args.code !== 'string' || !args.code.trim() || args.code.length > 80000) throw new Error('Actual Python analysis code required');
        const state = read(), cycle = state.cycle;
        if (!cycle || state.cycles.at(-1).synthesizedAt) throw new Error('No open planned cycle');
        const id = `run_${digest({ actor, cycle, requestId: args.requestId, code: args.code }).slice(0, 20)}`, jobDir = path.join(root, 'jobs', id), outputDir = path.join(jobDir, 'output');
        fs.mkdirSync(outputDir, { recursive: true }); fs.writeFileSync(path.join(jobDir, 'script.py'), args.code);
