    }
  }
  db.prepare('INSERT OR IGNORE INTO state(id,json) VALUES (1,?)').run(JSON.stringify({ version: 0, cycle: 0, cycles: [], claims: [], sources: {}, jobs: {}, queries: [], audit: null }));
  const read = () => JSON.parse(db.prepare('SELECT json FROM state WHERE id=1').get().json);
  const mutate = (change, advanceVersion = true) => {
    db.exec('BEGIN IMMEDIATE');
    try {
      const state = read(); const result = change(state);
