      inputDirectoryInContainer: '/input', outputDirectoryInContainer: '/output',
      cycles: state.cycles, claims: state.claims, sources: Object.values(state.sources).map(({ id, url, title, sha256, fullText }) => ({ id, url, title, sha256, fullText })),
        jobs: Object.values(state.jobs).map(job=>({id:job.id,actor:job.actor,cycle:job.cycle,status:job.status,codeSha256:job.codeSha256,artifacts:job.artifacts,jobDir:job.jobDir,error:job.error?.slice(0,2000)})), audit: state.audit,
