        }
        const resultFile = path.join(outputDir, 'results.json');
        let metrics;
        try { metrics = JSON.parse(fs.readFileSync(resultFile, 'utf8')); } catch { success = false; }
        if (!artifacts.length) success = false;
        const result = { ...record, status: success ? 'succeeded' : 'failed', finishedAt: now(), metrics, artifacts, stdout: stdout.slice(-12000), stderr: stderr.slice(-12000), command, jobDir };
