      const local = path.join(process.cwd(), ...relative.split('/')); fs.mkdirSync(local, { recursive: true });
      const exportState = actor === 'synthesis' || actor === 'audit' ? context() : { actor, cycle, jobs: Object.values(state.jobs).filter(job => job.actor === actor && job.cycle === state.cycle), sources: actor === 'literature' ? Object.values(state.sources) : [] };
