      if (actor === 'analysis') for (const job of Object.values(state.jobs).filter(job => job.actor === actor && job.cycle === state.cycle)) {
        fs.copyFileSync(path.join(job.jobDir, 'script.py'), path.join(local, `${job.id}.py`));
        for (const artifact of job.artifacts ?? []) fs.copyFileSync(path.join(job.jobDir, 'output', artifact.file), path.join(local, `${job.id}-${artifact.file}`));
