    },
    record_audit: async args => {
      requireRole(actor, ['audit']);
      return once('record_audit', args, async () => mutate(state => {
        if (state.cycle !== config.maxCycles || state.cycles.some(cycle => !cycle.synthesizedAt || cycle.trajectories.length !== 2)) throw new Error('All authorized cycles must have actual parallel trajectories and synthesis');
