        if (typeof args.assessment !== 'string' || !args.assessment.trim()) throw new Error('Actual audit rationale required');
        state.audit = { at: now(), checkedClaimIds: args.checkedClaimIds, assessment: args.assessment, passed: args.passed === true, note: 'Protocol evidence audit, not reproduction of original paper numerical results or expert validation.' };
        return state.audit;
      }));
    }
