const plain = html => html.replace(/<script[\s\S]*?<\/script>/gi,'').replace(/<style[\s\S]*?<\/style>/gi,'').replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();
const normalize = value => plain(value).normalize('NFKD').replace(/\p{M}/gu,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function extractPrimary(raw,url,expectedTitle) {
  const parsed = new URL(url),text=plain(raw);
  if(text.length<1000||/checking your browser|access denied|just a moment|recaptcha/i.test(text.slice(0,2000)))throw new Error('Source is a challenge/error page, not verified full text');
  if(parsed.hostname==='arxiv.org'&&(!/^\/html\/\d{4}\.\d{4,5}(v\d+)?\/?$/.test(parsed.pathname)||!raw.includes('ltx_article')||!raw.includes('ltx_section')))throw new Error('arXiv abstract/metadata or missing article sections is not full text');
  if(parsed.hostname==='pmc.ncbi.nlm.nih.gov'&&(!/^\/articles\/PMC\d+\/?$/.test(parsed.pathname)||!/<meta[^>]+(?:citation_title|DC\.Title)/i.test(raw)||!/<(?:section|div)[^>]+(?:body|sec|article)/i.test(raw)))throw new Error('PMC full article structure is missing');
  if(parsed.hostname==='www.ebi.ac.uk'&&(!/^\/europepmc\/webservices\/rest\/PMC\d+\/fullTextXML$/.test(parsed.pathname)||!/<body\b/.test(raw)||!/<article-title\b/.test(raw)))throw new Error('Europe PMC full article XML is missing');
  const citation=raw.match(/<meta\b[^>]*\bname=["'](?:citation_title|DC\.Title)["'][^>]*\bcontent=["']([^"']+)["'][^>]*>/i)?.[1]
    ?? raw.match(/<meta\b[^>]*\bcontent=["']([^"']+)["'][^>]*\bname=["'](?:citation_title|DC\.Title)["'][^>]*>/i)?.[1]
    ?? raw.match(/<h1\b[^>]*class=["'][^"']*ltx_title_document[^"']*["'][^>]*>([\s\S]*?)<\/h1>/i)?.[1]
    ?? (parsed.hostname==='www.ebi.ac.uk'?raw.match(/<article-title\b[^>]*>([\s\S]*?)<\/article-title>/i)?.[1]:undefined);
  if(!citation)throw new Error('Cannot verify the actual article title from metadata');
  const title=plain(citation),expected=normalize(expectedTitle??''),observed=normalize(title);
  // Bibliographic identity is not LLM-assessed. Fail closed on a claimed title
  // mismatch; return the genuine metadata so the caller can correct its search.
  if(!expected||expected!==observed)throw new Error(`Primary title mismatch: requested ${JSON.stringify(expectedTitle)}, actual ${JSON.stringify(title)}. No accepted source ID was created.`);
  return{title,plain:text};
}
module.exports={extractPrimary};

