const { Server } = require('@modelcontextprotocol/sdk/server/index.js');
const { StdioServerTransport } = require('@modelcontextprotocol/sdk/server/stdio.js');
const { ListToolsRequestSchema, CallToolRequestSchema } = require('@modelcontextprotocol/sdk/types.js');
const { openStore } = require('./science-store.cjs');
const definitions = require('./tools.json');
const actor = process.argv[2];
const store = openStore(process.env.SCIENCEEVOLVE_TODO_SCIENCE_ROOT, actor);
const visible = definitions.filter(tool => tool.actors.includes(actor)).map(({ actors, ...tool }) => tool);
const server = new Server({ name: 'kosmos-evidence-tools', version: '0.1.0' }, { capabilities: { tools: {} } });
server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: visible }));
server.setRequestHandler(CallToolRequestSchema, async request => {
  const { name, arguments: args = {} } = request.params;
  if (!visible.some(tool => tool.name === name)) throw new Error('Tool not assigned to this actor');
  try { return { content: [{ type: 'text', text: JSON.stringify(await store.operations[name](args)) }] }; }
  catch (error) { return { isError: true, content: [{ type: 'text', text: error.message }] }; }
});
server.connect(new StdioServerTransport());
process.stdin.on('end', () => { store.close(); server.close().finally(() => process.exit()); });

