const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');
const { DatabaseSync } = require('node:sqlite');
const { extractPrimary } = require('./primary-source.cjs');
const { execFile } = require('node:child_process');
const { promisify } = require('node:util');
const execute = promisify(execFile);
const digest = value => createHash('sha256').update(typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value)).digest('hex');
const now = () => new Date().toISOString();
const roles = ['planner', 'manager', 'analysis', 'literature', 'synthesis', 'audit', 'main'];
const safeId = value => typeof value === 'string' && /^[a-zA-Z0-9_-]{1,100}$/.test(value);
function requireRole(actor, allowed) { if (!allowed.includes(actor)) throw new Error('Operation not assigned to this role'); }

function validateClaims(claims, state) {
  if (!Array.isArray(claims) || !claims.length || claims.length > 30) throw new Error('Supply 1..30 evidence-backed claims');
  const current = new Set(state.claims.map(claim => claim.id));
  const knownEvidence = new Set([...Object.keys(state.sources), ...Object.values(state.jobs).filter(job => job.status === 'succeeded').map(job => job.id)]);
  const seen = new Set();
  for (const claim of claims) {
    if (!safeId(claim.id) || current.has(claim.id) || seen.has(claim.id)) throw new Error('Duplicate or unsafe claim id');
    seen.add(claim.id);
    if (!['analysis', 'literature', 'interpretation'].includes(claim.kind) || typeof claim.text !== 'string' || !claim.text.trim() || claim.text.length > 6000) throw new Error('Invalid typed claim');
    if (!Array.isArray(claim.evidenceIds) || !claim.evidenceIds.length || claim.evidenceIds.some(id => !knownEvidence.has(id))) throw new Error('Unknown or missing provenance');
    if (claim.kind === 'analysis' && !claim.evidenceIds.some(id => Object.values(state.jobs).some(job => job.id === id && job.status === 'succeeded'))) throw new Error('Analysis claim needs an actual successful job');
    if (claim.kind === 'literature' && !claim.evidenceIds.some(id => state.sources[id]?.fullText)) throw new Error('Literature claim needs a retrieved source, not fabricated bibliography');
    for (const key of ['supports', 'contradicts', 'supersedes']) {
      if (claim[key] !== undefined && (!Array.isArray(claim[key]) || claim[key].some(id => !current.has(id)))) throw new Error('Relationships must reference already persisted claims');
    }
  }
}

function openStore(root, actor) {
  if (!path.isAbsolute(root) || !roles.includes(actor)) throw new Error('Explicit scientific state directory and known actor required');
  const config = JSON.parse(fs.readFileSync(path.join(root, 'settings.json'), 'utf8'));
  if (config.method !== 'kosmos' || !Number.isInteger(config.maxCycles) || config.maxCycles < 2) throw new Error('Invalid Kosmos experiment settings');
  const db = new DatabaseSync(path.join(root, 'world.sqlite'));
  db.exec('PRAGMA busy_timeout=5000');
  for(let attempt=0;;attempt++){
    try{
      if(db.prepare('PRAGMA journal_mode').get().journal_mode!=='wal') db.exec('PRAGMA journal_mode=WAL');
      db.exec('CREATE TABLE IF NOT EXISTS state (id INTEGER PRIMARY KEY, json TEXT NOT NULL); CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, hash TEXT NOT NULL, status TEXT NOT NULL, result TEXT);');
      break;
