        datasets:config.datasets.map(({name,file,sha256})=>({name,file,sha256})),primarySourceCatalog:actor==='literature'?(config.primarySourceCatalog??[]):undefined,
        instruction:trajectory?'This actor published real scientific evidence in this cycle. Preserve it; perform only remaining authorized delivery.':'Scientific work is NOT complete. Native role=delivery on a first worker turn permits business plus Git; it does NOT prove a closure-only turn. Predecessor/parent PRs cannot complete this worker. Execute this single-cycle assignment, publish_trajectory with genuine evidence, export the scientific results, then do your own Git delivery. Memory.md alone is not scientific output.'};
    },
