        synthesizedAt:cycle.synthesizedAt??null,addedClaimIds,trajectories:cycle.trajectories,
        assignment:complete?'Preserve this actual completed world-update receipt and supplement only authorized remaining delivery.':'Read both current published trajectories and actual run/source evidence. Discover and call update_world to create your own typed evidence-backed claims, then export the world and write the current-cycle synthesis report. Readiness or an upstream PR is not your completion.',
        nativeDeliveryBoundary:'Synthesis is a root business role. Use the exact current native Inbox branch, confirmed pushed head and direct target main; never copy the predecessor group/member PR target. This scientific tool does not grant Git or scheduling authority.'};
    },
      get_cycle_readiness: async () => {
        const state=read(),cycle=state.cycles.at(-1),actors=cycle?.trajectories.map(item=>item.actor)??[];
        const missing=['analysis','literature'].filter(actor=>!actors.includes(actor));
        const literature=cycle?.trajectories.filter(item=>item.actor==='literature')??[];
        const validLiterature=literature.length===1&&literature.every(item=>item.evidenceIds.every(id=>state.sources[id]?.titleVerified));
        return {cycle:state.cycle,ready:missing.length===0&&validLiterature,missingActors:missing,validLiterature,titleVerificationRequired:true,synthesisComplete:Boolean(cycle?.synthesizedAt),instruction:'Ready means prerequisites for synthesis, NOT that synthesis was done. Scientific publication and native Git integration are distinct. Do not close this group or dispatch synthesis with missing/invalid scientific trajectories; synthesis must read its own get_synthesis_assignment and actual world-update receipt.'};
      },
    query_world: async ({ query }) => mutate(state => {
      if (typeof query !== 'string' || !query.trim() || query.length > 2000) throw new Error('Specify a bounded scientific query');
      const terms = query.toLowerCase().split(/\W+/).filter(term => term.length > 2);
      const matches = state.claims.filter(claim => claim.status !== 'superseded').map(claim => ({ claim, rank: terms.filter(term => claim.text.toLowerCase().includes(term)).length }))
        .sort((a, b) => b.rank - a.rank).slice(0, 20).map(item => item.claim);
