        if (!Array.isArray(args.tasks) || args.tasks.length !== 2 || new Set(args.tasks.map(task => task.actor)).size !== 2 || !args.tasks.some(task => task.actor === 'analysis') || !args.tasks.some(task => task.actor === 'literature')) throw new Error('Plan one actual data and one literature trajectory in parallel');
        const used = args.usedClaimIds ?? [];
        if (used.some(id => !state.claims.some(claim => claim.id === id))) throw new Error('Unknown reused claim');
        if (state.cycle && (!used.length || !state.queries.some(q => q.actor === actor && q.cycle === state.cycle && used.every(id => q.claimIds.includes(id))))) throw new Error('Next cycle must actually query and consume earlier world-model claims');
        for (const task of args.tasks) if (typeof task.assignment !== 'string' || !task.assignment.trim() || task.assignment.length > 12000) throw new Error('Each trajectory needs a concrete assignment');
        state.cycle++; state.cycles.push({ cycle: state.cycle, tasks: args.tasks, usedClaimIds: used, trajectories: [], plannedAt: now(), plannedFromVersion: args.expectedVersion });
        return { cycle: state.cycle, tasks: args.tasks, usedClaimIds: used };
      }));
    },
    search_literature: async args => {
      requireRole(actor, ['literature']);
      if (typeof args.query !== 'string' || !args.query.trim() || args.query.length > 400) throw new Error('Bounded literature query required');
      const url = new URL('https://api.crossref.org/works'); url.searchParams.set('query', args.query); url.searchParams.set('rows', '5');
      const response = await fetch(url, { signal: AbortSignal.timeout(45000) }); if (!response.ok) throw new Error(`Crossref HTTP ${response.status}`);
      const body = await response.json();
      return { query: args.query, url: String(url), results: body.message.items.map(item => ({ doi: item.DOI, title: item.title?.[0], url: item.URL, abstract: item.abstract, authors: item.author?.slice(0, 3).map(a => `${a.given ?? ''} ${a.family ?? ''}`), note: 'Metadata only. Retrieve primary full text before treating as read evidence.' })) };
    },
    read_primary_source: async args => {
      requireRole(actor, ['literature']);
      return once('read_primary_source', args, async () => {
        let url = new URL(args.url);
        const allowed = new Set(['arxiv.org', 'pmc.ncbi.nlm.nih.gov', 'www.ebi.ac.uk']);
        if (url.protocol !== 'https:' || !allowed.has(url.hostname) || url.username || url.password) throw new Error('Only public arXiv/PMC primary full-text sources are enabled');
        let response;
        for (let hop = 0; hop < 4; hop++) {
          response = await fetch(url, { redirect: 'manual', signal: AbortSignal.timeout(45000) });
          if (response.status < 300 || response.status >= 400) break;
          url = new URL(response.headers.get('location'), url);
          if (url.protocol !== 'https:' || !allowed.has(url.hostname)) throw new Error('Refusing source redirect outside the enabled public hosts');
        }
        if (!response.ok) throw new Error(`Primary source HTTP ${response.status}`);
        if (Number(response.headers.get('content-length')) > 4 * 1024 ** 2) throw new Error('Source exceeds 4 MiB');
        const chunks = []; let length = 0;
        for await (const chunk of response.body) { length += chunk.length; if (length > 4 * 1024 ** 2) throw new Error('Source exceeds 4 MiB'); chunks.push(chunk); }
        const raw = Buffer.concat(chunks).toString('utf8');
        const verified = extractPrimary(raw, String(url), args.title), plain = verified.plain;
        const sha256 = digest(raw), id = `source_${sha256.slice(0, 20)}`;
        const offset = Number.isInteger(args.offset) && args.offset >= 0 ? args.offset : 0;
        const source = { id, url: String(url), title: verified.title, requestedTitle: args.title, sha256, fullText: true, titleVerified: true, retrievedAt: now(), bytes: length, characters: plain.length };
        fs.mkdirSync(path.join(root, 'sources'), { recursive: true }); fs.writeFileSync(path.join(root, 'sources', `${id}.txt`), plain); fs.writeFileSync(path.join(root, 'sources', `${id}.html`), raw);
        mutate(state => { state.sources[id] = source; });
        return { ...source, offset, text: plain.slice(offset, offset + 18000), truncated: offset + 18000 < plain.length };
      });
    },
    run_analysis: async args => {
      requireRole(actor, ['analysis']);
      return once('run_analysis', args, async () => {
        if (typeof args.code !== 'string' || !args.code.trim() || args.code.length > 80000) throw new Error('Actual Python analysis code required');
        const state = read(), cycle = state.cycle;
        if (!cycle || state.cycles.at(-1).synthesizedAt) throw new Error('No open planned cycle');
        const id = `run_${digest({ actor, cycle, requestId: args.requestId, code: args.code }).slice(0, 20)}`, jobDir = path.join(root, 'jobs', id), outputDir = path.join(jobDir, 'output');
        fs.mkdirSync(outputDir, { recursive: true }); fs.writeFileSync(path.join(jobDir, 'script.py'), args.code);
        const record = { id, actor, cycle, codeSha256: digest(args.code), status: 'running', startedAt: now(), image: config.image, datasetHashes: config.datasets.map(({ file, sha256 }) => ({ file, sha256 })) };
        mutate(s => { s.jobs[id] = record; });
        const command = ['run', '--rm', '--name', `scienceevolve-${id}`, '--label', `scienceevolve.todo.job=${id}`, '--network', 'none', '--read-only', '--cap-drop', 'ALL', '--security-opt', 'no-new-privileges', '--cpus', '2', '--memory', '2g', '--pids-limit', '128', '--tmpfs', '/tmp:rw,size=256m', '--mount', `type=bind,source=${config.inputDir},target=/input,readonly`, '--mount', `type=bind,source=${path.join(jobDir, 'script.py')},target=/work/script.py,readonly`, '--mount', `type=bind,source=${outputDir},target=/output`, config.image, 'python', '/work/script.py'];
        let stdout = '', stderr = '', success = false;
        try { ({ stdout, stderr } = await execute('docker', command, { timeout: 240000, maxBuffer: 2 * 1024 ** 2, windowsHide: true })); success = true; }
        catch (error) {
          stdout = error.stdout ?? ''; stderr = error.stderr ?? String(error.message);
          if (error.killed) {
            const label = await execute('docker', ['inspect', '--format', '{{index .Config.Labels "scienceevolve.todo.job"}}', `scienceevolve-${id}`], { windowsHide: true }).catch(() => null);
            if (label?.stdout.trim() === id) await execute('docker', ['stop', '--time', '5', `scienceevolve-${id}`], { windowsHide: true }).catch(() => {});
          }
        }
        fs.writeFileSync(path.join(jobDir, 'stdout.log'), stdout); fs.writeFileSync(path.join(jobDir, 'stderr.log'), stderr);
        const artifacts = [];
        for (const entry of fs.readdirSync(outputDir, { withFileTypes: true })) {
          if (!entry.isFile() || entry.isSymbolicLink() || fs.statSync(path.join(outputDir, entry.name)).size > 8 * 1024 ** 2) continue;
          const bytes = fs.readFileSync(path.join(outputDir, entry.name));
          artifacts.push({ file: entry.name, sha256: digest(bytes), bytes: bytes.length });
        }
        const resultFile = path.join(outputDir, 'results.json');
        let metrics;
        try { metrics = JSON.parse(fs.readFileSync(resultFile, 'utf8')); } catch { success = false; }
        if (!artifacts.length) success = false;
        const result = { ...record, status: success ? 'succeeded' : 'failed', finishedAt: now(), metrics, artifacts, stdout: stdout.slice(-12000), stderr: stderr.slice(-12000), command, jobDir };
        mutate(s => { s.jobs[id] = result; }); return result;
      });
    },
    publish_trajectory: async args => {
      requireRole(actor, ['analysis', 'literature']);
      return once('publish_trajectory', args, async () => mutate(state => {
        const cycle = state.cycles.at(-1); if (!cycle || cycle.synthesizedAt) throw new Error('No active cycle');
        if (cycle.trajectories.some(item => item.actor === actor)) throw new Error('Trajectory already published');
        if (typeof args.finding !== 'string' || !args.finding.trim()) throw new Error('Actual trajectory findings required');
        const evidence = args.evidenceIds;
        if (!Array.isArray(evidence) || !evidence.length) throw new Error('Actual evidence required');
        for (const id of evidence) {
          if (actor === 'analysis' && !(state.jobs[id]?.status === 'succeeded' && state.jobs[id].cycle === state.cycle)) throw new Error('Analysis evidence must reference this cycle actual container results');
            if (actor === 'literature' && !(state.sources[id]?.fullText && state.sources[id]?.titleVerified)) throw new Error('Literature evidence must reference identity-verified retrieved primary sources');
        }
        const used = args.usedClaimIds ?? [];
        if (used.some(id => !state.claims.some(claim => claim.id === id))) throw new Error('Unknown reused claim');
        if (state.cycle > 1 && (!used.length || !state.queries.some(q => q.actor === actor && q.cycle === state.cycle && used.every(id => q.claimIds.includes(id))))) throw new Error('Later trajectory must actually read and consume previous claims');
        const record = { actor, cycle: state.cycle, finding: args.finding, evidenceIds: evidence, usedClaimIds: used, publishedAt: now() };
        cycle.trajectories.push(record); return record;
      }));
    },
    update_world: async args => {
      requireRole(actor, ['synthesis']);
      return once('update_world', args, async () => mutate(state => {
        const cycle = state.cycles.at(-1); if (!cycle || cycle.synthesizedAt || cycle.trajectories.length !== 2) throw new Error('Exactly two completed parallel trajectories required before world synthesis');
        validateClaims(args.claims, state);
        for (const claim of args.claims) {
          for (const id of claim.supersedes ?? []) state.claims.find(old => old.id === id).status = 'superseded';
          state.claims.push({ ...claim, cycle: state.cycle, createdAt: now(), status: 'active' });
        }
        cycle.synthesizedAt = now(); cycle.addedClaimIds = args.claims.map(claim => claim.id);
        return { version: state.version + 1, cycle: state.cycle, addedClaimIds: cycle.addedClaimIds };
      }));
    },
    write_evidence_artifacts: async () => {
      requireRole(actor, ['planner', 'analysis', 'literature', 'synthesis', 'audit']);
      const state = read(); const cycle = state.cycles.at(-1);
      const relative = `results/${actor}/cycle-${state.cycle}`;
      const local = path.join(process.cwd(), ...relative.split('/')); fs.mkdirSync(local, { recursive: true });
      const exportState = actor === 'synthesis' || actor === 'audit' ? context() : { actor, cycle, jobs: Object.values(state.jobs).filter(job => job.actor === actor && job.cycle === state.cycle), sources: actor === 'literature' ? Object.values(state.sources) : [] };
      fs.writeFileSync(path.join(local, 'evidence.json'), JSON.stringify(exportState, null, 2));
      if (actor === 'analysis') for (const job of Object.values(state.jobs).filter(job => job.actor === actor && job.cycle === state.cycle)) {
        fs.copyFileSync(path.join(job.jobDir, 'script.py'), path.join(local, `${job.id}.py`));
        for (const artifact of job.artifacts ?? []) fs.copyFileSync(path.join(job.jobDir, 'output', artifact.file), path.join(local, `${job.id}-${artifact.file}`));
      }
      return { relativePath: relative, evidenceSha256: digest(fs.readFileSync(path.join(local, 'evidence.json'))), note: 'Commit these files and your report through the assigned native SDK Git tools; this tool does not commit or complete the task.' };
    },
    read_reference_results: async () => {
      requireRole(actor, ['audit']);
      const bytes = fs.readFileSync(config.referenceFile);
      return { sha256: digest(bytes), text: bytes.toString('utf8'), note: 'Published reference is audit-only, not this run analysis input.' };
    },
    record_audit: async args => {
      requireRole(actor, ['audit']);
      return once('record_audit', args, async () => mutate(state => {
        if (state.cycle !== config.maxCycles || state.cycles.some(cycle => !cycle.synthesizedAt || cycle.trajectories.length !== 2)) throw new Error('All authorized cycles must have actual parallel trajectories and synthesis');
        if (!state.claims.some(claim => claim.kind === 'analysis') || !state.claims.some(claim => claim.kind === 'literature')) throw new Error('Typed data and literature claims required');
        if (Object.values(state.sources).filter(source => source.fullText).length < 2) throw new Error('Two distinct actually retrieved primary sources required');
        if (!state.cycles.slice(1).every(cycle => cycle.usedClaimIds.length && cycle.trajectories.every(t => t.usedClaimIds.length))) throw new Error('Cross-cycle world-model consumption not proven');
        if (!Array.isArray(args.checkedClaimIds) || state.claims.some(claim => !args.checkedClaimIds.includes(claim.id))) throw new Error('Independently inspect every claim before audit');
        if (typeof args.assessment !== 'string' || !args.assessment.trim()) throw new Error('Actual audit rationale required');
        state.audit = { at: now(), checkedClaimIds: args.checkedClaimIds, assessment: args.assessment, passed: args.passed === true, note: 'Protocol evidence audit, not reproduction of original paper numerical results or expert validation.' };
        return state.audit;
      }));
    }
  };
  return { operations, context, close: () => db.close(), read };
}
module.exports = { openStore, validateClaims, digest };

